WITH consent_status AS (
  SELECT c.customer_id, CASE WHEN c.marketing_opt_in IS NULL THEN 1 ELSE 0 END AS never_asked
  FROM customers AS c
)
SELECT sum(cs.never_asked) AS never_asked_count
FROM consent_status AS cs;

